kg_fingerprint.cypher:
MATCH (s:Study) WITH count(s) AS studies, max(toInteger(substring(s.identifier, 4))) AS study_num_max
MATCH (a:Assay) WITH studies, study_num_max, count(a) AS assays, sum(toInteger('0x' + substring(a.identifier, size(a.identifier) - 12))) AS assay_md5_sum48
CALL { MATCH (g:MGene) RETURN count(g) AS mgenes }
CALL { MATCH (h:Gene) RETURN count(h) AS genes }
CALL { MATCH (mi:Mission) RETURN count(mi) AS missions }
CALL { MATCH ()-[r:MEASURED_DIFFERENTIAL_EXPRESSION_ASmMG]->() RETURN count(r) AS de_edges }
CALL { MATCH ()-[r:IS_ORTHOLOG_MGiG]->() RETURN count(r) AS ortholog_edges }
RETURN studies, study_num_max, assays, assay_md5_sum48, mgenes, genes, missions, de_edges, ortholog_edges
